import type { ISODate, ISODateTime, PayType } from '../api/types';

const WEEKDAYS_SHORT = ['Ня', 'Да', 'Мя', 'Лх', 'Пү', 'Ба', 'Бя'];
const WEEKDAYS_LONG = ['Ням', 'Даваа', 'Мягмар', 'Лхагва', 'Пүрэв', 'Баасан', 'Бямба'];

export function money(amount: number): string {
  return `${Math.round(amount).toLocaleString('en-US')}₮`;
}

export function pay(type: PayType, amount: number): string {
  return `${money(amount)} / ${type === 'hourly' ? 'цаг' : 'сар'}`;
}

const pad = (n: number) => String(n).padStart(2, '0');

export function toISODate(d: Date): ISODate {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

export function parseDate(iso: ISODate): Date {
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
  return new Date(y, m - 1, d);
}

export function todayISO(): ISODate {
  return toISODate(new Date());
}

export function addDays(iso: ISODate, days: number): ISODate {
  const d = parseDate(iso);
  d.setDate(d.getDate() + days);
  return toISODate(d);
}

/** Monday of the week containing `iso`. */
export function weekStart(iso: ISODate): ISODate {
  const d = parseDate(iso);
  const diff = (d.getDay() + 6) % 7;
  d.setDate(d.getDate() - diff);
  return toISODate(d);
}

/** "10/17" */
export function shortDate(iso: ISODate): string {
  const d = parseDate(iso);
  return `${pad(d.getMonth() + 1)}/${pad(d.getDate())}`;
}

/** "2026.06" */
export function monthDot(iso: ISODate): string {
  return iso.slice(0, 7).replace('-', '.');
}

export function weekdayShort(iso: ISODate): string {
  return WEEKDAYS_SHORT[parseDate(iso).getDay()];
}

/** "Бямба, 10-р сарын 17" */
export function longDate(iso: ISODate): string {
  const d = parseDate(iso);
  return `${WEEKDAYS_LONG[d.getDay()]}, ${d.getMonth() + 1}-р сарын ${d.getDate()}`;
}

export function timeHM(iso: ISODateTime): string {
  const d = new Date(iso);
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export function nowHM(): string {
  return timeHM(new Date().toISOString());
}

export function monthsBetween(start: ISODate, end?: ISODate): number {
  const a = parseDate(start);
  const b = end ? parseDate(end) : new Date();
  return Math.max(1, (b.getFullYear() - a.getFullYear()) * 12 + b.getMonth() - a.getMonth() + 1);
}

/** Relative time in Mongolian: "4 цагийн өмнө", "Өчигдөр", "10/12". */
export function relativeTime(iso: ISODateTime): string {
  const then = new Date(iso);
  const now = new Date();
  const mins = Math.round((now.getTime() - then.getTime()) / 60000);
  if (mins < 1) return 'Дөнгөж сая';
  if (mins < 60) return `${mins} минутын өмнө`;
  const hours = Math.round(mins / 60);
  if (hours < 24 && then.getDate() === now.getDate()) return `${hours} цагийн өмнө`;
  const days = Math.round(
    (parseDate(toISODate(now)).getTime() - parseDate(toISODate(then)).getTime()) / 86400000,
  );
  if (days === 1) return 'Өчигдөр';
  if (days < 7) return `${days} өдрийн өмнө`;
  return shortDate(toISODate(then));
}

/** Chat-style stamp: time today, "Өчигдөр", or date. */
export function chatStamp(iso: ISODateTime): string {
  const then = new Date(iso);
  const today = todayISO();
  const day = toISODate(then);
  if (day === today) return timeHM(iso);
  if (day === addDays(today, -1)) return 'Өчигдөр';
  return shortDate(day);
}

export function initials(name: string): string {
  return name.trim().charAt(0).toUpperCase();
}

export function hoursBetween(start: string, end: string): number {
  const [h1, m1] = start.split(':').map(Number);
  const [h2, m2] = end.split(':').map(Number);
  return Math.max(0, h2 * 60 + m2 - (h1 * 60 + m1)) / 60;
}
